              a
            </div>
          </ReactGridLayout>
        );

        const grid = container.querySelector(".react-grid-layout");

        // Perform multiple drag in/out cycles
        for (let cycle = 0; cycle < 5; cycle++) {
          // Drag in
          act(() => {
