      );

      // Rapidly rerender multiple times (simulates concurrent updates)
      act(() => {
        for (let i = 0; i < 5; i++) {
          rerender(
            <ReactGridLayout
              className="layout"
              cols={12}
              rowHeight={30}
              width={1200 + i * 10}
