      for (let run = 0; run < 5; run++) {
        const layout = generateRandomLayout(50, 12, 5);

        const compacted1 = fastHorizontalCompactor.compact(layout, 12);
        const compacted2 = fastHorizontalCompactor.compact(compacted1, 12);

        // Compare positions
