        cols={{ lg: 12, sm: 6 }}
        onLayoutChange={onLayoutChange}
      >
        <div key="a">A</div>
      </ResponsiveRGL>
    );

    // Trigger resize to sm (no layout provided)
    act(() => {
      global.triggerResize(600, 400);
    });

    // Should still render without error and generate a layout
    expect(onLayoutChange).toHaveBeenCalled();
    const lastLayout =
      onLayoutChange.mock.calls[onLayoutChange.mock.calls.length - 1][0];
    expect(lastLayout).toHaveLength(1);
    expect(lastLayout[0].i).toBe("a");
  })

it("defers ResizeObserver updates via requestAnimationFrame (#1959)", () => {
    // Track requestAnimationFrame calls
    let rafCallCount = 0;
    const originalRaf = global.requestAnimationFrame;
    global.requestAnimationFrame = jest.fn(cb => {
      rafCallCount++;
      cb(0);
      return rafCallCount;
    });

    render(
      <WidthProvidedRGL layout={[{ i: "a", x: 0, y: 0, w: 2, h: 2 }]} cols={12}>
        <div key="a">A</div>
      </WidthProvidedRGL>
    );

    // Clear initial RAF calls
    rafCallCount = 0;

    // Trigger resize
    act(() => {
      global.triggerResize(800, 600);
    });

    // RAF should have been called to defer the state update
    expect(rafCallCount).toBeGreaterThan(0);

    // Restore
    global.requestAnimationFrame = originalRaf;
  })

it("allowOverlap=true with compactType=null preserves overlapping items", () => {
    const onLayoutChange = jest.fn();

    // Create layout with intentionally overlapping items
    const layout = [
      { i: "a", x: 0, y: 0, w: 4, h: 4 },
      { i: "b", x: 2, y: 2, w: 4, h: 4 } // Overlaps with 'a'
    ];

    render(
      <ReactGridLayout
        layout={layout}
        width={1200}
        cols={12}
        compactType={null}
        allowOverlap={true}
        onLayoutChange={onLayoutChange}
      >
        <div key="a">A</div>
        <div key="b">B</div>
      </ReactGridLayout>
    );

    expect(onLayoutChange).toHaveBeenCalled();
    const [resultLayout] = onLayoutChange.mock.calls[0];

    // Items should remain in their original positions (overlapping)
    const itemA = resultLayout.find(l => l.i === "a");
    const itemB = resultLayout.find(l => l.i === "b");

    expect(itemA.x).toBe(0);
    expect(itemA.y).toBe(0);
    expect(itemB.x).toBe(2);
    expect(itemB.y).toBe(2);
  })

